from pathlib import Path
p=Path('index.html');s=p.read_text(encoding='utf-8')
s=s.replace('characters.js?v=11','characters.js?v=12').replace('avatar3d.js?v=11','avatar3d.js?v=12').replace('motion.js?v=9','motion.js?v=12')
s=s.replace("demoPose:track.avatar>=4?(track.action==='wave'||track.action==='raise'?'wave':track.action==='arms'?'arms':'stand'):undefined,", "demoAction:track.avatar>=4?track.action:undefined,demoPose:track.avatar>=4&&!track.action?'stand':undefined,")
s=s.replace('avatar:track.avatar,fullBody:track.avatar>=4,observedAt:', 'avatar:track.avatar,action:track.action,fullBody:track.avatar>=4,observedAt:')
s=s.replace('<option value="stand">站立</option><option value="wave">挥手</option><option value="arms">展开双臂</option><option value="squat">下蹲</option><option value="step">抬腿</option>', '<option value="stand">站立</option><option value="forehead">扶额</option><option value="head">双手抱头</option><option value="turn">转头</option><option value="raise">单手举高</option><option value="handsup">双手举高</option><option value="wave">挥手</option><option value="arms">展开双臂</option><option value="tilt">歪头</option><option value="mouth">张嘴</option><option value="squat">下蹲</option><option value="step">抬腿</option>')
s=s.replace("demoPose:avatar>=4?$('previewAction').value:undefined", "demoAction:avatar>=4&&Motion.actions[$('previewAction').value]?$('previewAction').value:undefined,demoPose:avatar>=4?$('previewAction').value:undefined")
s=s.replace('支持身体动作和转头，暂无眨眼、张嘴表情', '支持 9 个动作，暂无眨眼表情')
s=s.replace('支持转头、挥手、展开双臂、下蹲和抬腿。当前模型暂无眨眼、张嘴表情。', '支持前端列出的 9 个动作。张嘴为新增形变，当前模型暂无眨眼表情。')
p.write_text(s,encoding='utf-8')
